window.QB_ROUNDS = [{"id":"classic","name":{"en":"Classic","nl":"Klassiek","fr":"Classique","de":"Klassisch","es":"Clásicas"},"rounds":[{"id":"classic","en":"Multiple choice","nl":"Meerkeuze","fr":"Choix multiple","de":"Multiple Choice","es":"Opción múltiple","desc":{"en":"Four options, one is right.","nl":"Vier opties, één is juist.","fr":"Quatre choix, un seul est juste.","de":"Vier Antworten, eine ist richtig.","es":"Cuatro opciones, una es la buena."}},{"id":"trueFalse","en":"True or bluff","nl":"Waar of bluf","fr":"Vrai ou bluff","de":"Wahr oder Bluff","es":"Verdad o farol","desc":{"en":"A statement: true or not?","nl":"Een stelling: waar of niet?","fr":"Une affirmation : vraie ou pas ?","de":"Eine Aussage: stimmt sie oder nicht?","es":"Una afirmación: ¿es cierta o no?"}},{"id":"open","en":"Open answer","nl":"Open vraag","fr":"Réponse libre","de":"Offene Frage","es":"Respuesta abierta","desc":{"en":"Type the answer; the quizmaster can overrule.","nl":"Typ het antwoord; de quizmaster kan bijsturen.","fr":"Tapez la réponse ; le quizmaster peut corriger.","de":"Tippe die Antwort; der Quizmaster kann überstimmen.","es":"Escribe la respuesta; el presentador puede corregirla."}},{"id":"closest","en":"Closest wins","nl":"Wie zit het dichtst","fr":"Le plus proche gagne","de":"Am nächsten dran","es":"El más cercano gana","desc":{"en":"Guess a number. The closest team scores, spot on counts double.","nl":"Schat een getal. Het dichtste team scoort, exact telt dubbel.","fr":"Estimez un nombre. L'équipe la plus proche marque, pile poil compte double.","de":"Schätze eine Zahl. Das nächste Team punktet, ein Volltreffer zählt doppelt.","es":"Adivina un número. Puntúa el equipo más cercano; si aciertas de lleno, cuenta doble."}},{"id":"orderUp","en":"In the right order","nl":"In de juiste volgorde","fr":"Dans le bon ordre","de":"In die richtige Reihenfolge","es":"En orden","desc":{"en":"Put the items in order: oldest first, smallest first, and so on.","nl":"Zet alles in volgorde: oudste eerst, kleinste eerst, enzovoort.","fr":"Remettez dans l'ordre : du plus ancien, du plus petit, etc.","de":"Bring die Dinge in die Reihenfolge: das Älteste zuerst, das Kleinste zuerst und so weiter.","es":"Ordena los elementos: el más antiguo primero, el más pequeño primero, etc."}},{"id":"pairUp","en":"Make pairs","nl":"Paren maken","fr":"Faites les paires","de":"Paare bilden","es":"Haz parejas","desc":{"en":"Match every item on the left with one on the right.","nl":"Koppel elk item links aan één item rechts.","fr":"Associez chaque élément de gauche à un élément de droite.","de":"Ordne jedem Element links eines rechts zu.","es":"Une cada elemento de la izquierda con uno de la derecha."}},{"id":"fiveFacts","en":"Five facts","nl":"Vijf weetjes","fr":"Cinq faits","de":"Fünf Fakten","es":"Cinco datos","desc":{"en":"One open question with five keywords. Every keyword you find scores.","nl":"Eén open vraag met vijf sleutelwoorden. Elk woord dat je vindt, scoort.","fr":"Une question ouverte avec cinq mots-clés. Chaque mot trouvé rapporte.","de":"Eine offene Frage mit fünf Stichworten. Jedes gefundene Stichwort punktet.","es":"Una pregunta abierta con cinco palabras clave. Cada palabra clave que encuentres puntúa."}}]},{"id":"visual","name":{"en":"Pictures","nl":"Beeld","fr":"Images","de":"Bilder","es":"Imágenes"},"rounds":[{"id":"picture","en":"Picture round","nl":"Fotoronde","fr":"Manche photo","de":"Bilderrunde","es":"Ronda de imágenes","desc":{"en":"What or who is in the picture?","nl":"Wat of wie staat er op de foto?","fr":"Quoi ou qui est sur la photo ?","de":"Was oder wer ist auf dem Bild?","es":"¿Qué o quién sale en la imagen?"}},{"id":"zoomOut","en":"Zoom out","nl":"Uitzoomen","fr":"Zoom arrière","de":"Zoom raus","es":"Alejar el zoom","desc":{"en":"The picture starts zoomed in far and slowly zooms out. Early is worth more.","nl":"De foto start ver ingezoomd en zoomt traag uit. Vroeg raden levert meer op.","fr":"L'image démarre très zoomée puis recule lentement. Trouver tôt rapporte plus.","de":"Das Bild ist erst stark vergrößert und zoomt langsam heraus. Früh raten bringt mehr.","es":"La imagen empieza muy ampliada y se va alejando poco a poco. Cuanto antes, más vale."}},{"id":"pixelFog","en":"Pixel fog","nl":"Pixelmist","fr":"Brouillard de pixels","de":"Pixelnebel","es":"Niebla de píxeles","desc":{"en":"Big blocks that slowly get sharp. The sooner you know, the more you score.","nl":"Grote blokken die langzaam scherp worden. Hoe sneller je het weet, hoe meer punten.","fr":"De gros blocs qui deviennent nets. Plus vite vous trouvez, plus vous marquez.","de":"Grobe Blöcke, die langsam scharf werden. Je früher du es weißt, desto mehr Punkte.","es":"Bloques grandes que poco a poco se aclaran. Cuanto antes lo sepas, más puntos."}},{"id":"silhouette","en":"Shadow play","nl":"Schaduwspel","fr":"Ombres chinoises","de":"Schattenspiel","es":"Sombras chinescas","desc":{"en":"Only the outline is shown. Who or what is it?","nl":"Je ziet alleen de omtrek. Wie of wat is het?","fr":"Seule la silhouette est visible. Qui ou quoi est-ce ?","de":"Nur der Umriss ist zu sehen. Wer oder was ist das?","es":"Solo se ve la silueta. ¿Quién o qué es?"}},{"id":"oddOneOut","en":"Odd one out","nl":"Wie hoort er niet bij?","fr":"L'intrus","de":"Was passt nicht","es":"El intruso","desc":{"en":"Three or four pictures. Which one does not belong?","nl":"Drie of vier foto's. Welke hoort er niet bij?","fr":"Trois ou quatre images. Laquelle n'a rien à faire là ?","de":"Drei oder vier Bilder. Welches gehört nicht dazu?","es":"Tres o cuatro imágenes. ¿Cuál no encaja?"}},{"id":"emoji","en":"Emoji riddle","nl":"Emoji-raadsel","fr":"Rébus emoji","de":"Emoji-Rätsel","es":"Acertijo emoji","desc":{"en":"A film, song or saying told in emoji.","nl":"Een film, liedje of gezegde in emoji.","fr":"Un film, une chanson ou une expression en emoji.","de":"Ein Film, ein Lied oder ein Sprichwort in Emoji erzählt.","es":"Una película, canción o refrán contado con emojis."}},{"id":"mapDrop","en":"Pin it","nl":"Prik het","fr":"Épinglez-le","de":"Pin setzen","es":"Pon la chincheta","desc":{"en":"Tap the spot on a map or picture. The closest pin wins.","nl":"Tik de plek aan op een kaart of foto. De dichtste pin wint.","fr":"Touchez l'endroit sur une carte ou une image. L'épingle la plus proche gagne.","de":"Tippe auf die Stelle auf einer Karte oder einem Bild. Der nächste Pin gewinnt.","es":"Toca el punto en un mapa o una imagen. Gana la chincheta más cercana."}},{"id":"clipRecall","en":"Sharp eyes","nl":"Goed gekeken","fr":"Bien vu","de":"Adleraugen","es":"Ojo de lince","desc":{"en":"Watch a short video, then type every detail you remember.","nl":"Kijk naar een korte video en typ alle details die je onthouden hebt.","fr":"Regardez une courte vidéo, puis tapez tous les détails retenus.","de":"Sieh dir ein kurzes Video an und tippe dann jedes Detail, an das du dich erinnerst.","es":"Mira un vídeo corto y escribe todos los detalles que recuerdes."}}]},{"id":"audio","name":{"en":"Audio","nl":"Audio","fr":"Audio","de":"Audio","es":"Audio"},"rounds":[{"id":"music","en":"Music round","nl":"Muziekronde","fr":"Manche musicale","de":"Musikrunde","es":"Ronda musical","desc":{"en":"Play a fragment: who sings it, or what is it called?","nl":"Speel een fragment: wie zingt het, of hoe heet het?","fr":"Un extrait : qui chante, ou quel est le titre ?","de":"Spiel einen Ausschnitt: Wer singt das, oder wie heißt es?","es":"Suena un fragmento: ¿quién la canta o cómo se llama?"}},{"id":"introSprint","en":"Intro sprint","nl":"Introsprint","fr":"Sprint d'intro","de":"Intro-Sprint","es":"Sprint de intros","desc":{"en":"The intro grows: 1, 2, 4, then 8 seconds. Guess early for more points.","nl":"Het intro groeit: 1, 2, 4 en dan 8 seconden. Vroeg raden levert meer op.","fr":"L'intro s'allonge : 1, 2, 4 puis 8 secondes. Plus tôt, plus de points.","de":"Das Intro wächst: 1, 2, 4, dann 8 Sekunden. Früh raten bringt mehr Punkte.","es":"La intro crece: 1, 2, 4 y luego 8 segundos. Adivina pronto y gana más puntos."}},{"id":"rewind","en":"Backwards","nl":"Achterstevoren","fr":"À l'envers","de":"Rückwärts","es":"Al revés","desc":{"en":"The song plays backwards. Which one is it?","nl":"Het nummer speelt achterstevoren. Welk is het?","fr":"La chanson passe à l'envers. Laquelle est-ce ?","de":"Das Lied läuft rückwärts. Welches ist es?","es":"La canción suena al revés. ¿Cuál es?"}},{"id":"soundCheck","en":"What's that sound?","nl":"Welk geluid?","fr":"Quel est ce bruit ?","de":"Was ist das für ein Geräusch?","es":"¿Qué es ese sonido?","desc":{"en":"An animal, a machine, a noise from daily life. What makes it?","nl":"Een dier, een machine, een geluid van elke dag. Wat maakt het?","fr":"Un animal, une machine, un bruit du quotidien. Qui le fait ?","de":"Ein Tier, eine Maschine, ein Alltagsgeräusch. Was macht das?","es":"Un animal, una máquina, un ruido cotidiano. ¿Qué lo hace?"}},{"id":"lyricGap","en":"Missing lyric","nl":"Ontbrekend woord","fr":"Parole manquante","de":"Textlücke","es":"Letra perdida","desc":{"en":"One word of a song line is gone. Fill it in.","nl":"Er ontbreekt één woord in een songregel. Vul het aan.","fr":"Un mot manque dans une ligne de chanson. Complétez.","de":"Ein Wort einer Liedzeile fehlt. Füll es aus.","es":"Falta una palabra de un verso. Complétalo."}}]},{"id":"speed","name":{"en":"Speed","nl":"Snelheid","fr":"Vitesse","de":"Tempo","es":"Velocidad"},"rounds":[{"id":"speed","en":"Speed round","nl":"Snelheidsronde","fr":"Manche rapide","de":"Blitzrunde","es":"Ronda rápida","desc":{"en":"Ten seconds a question. Fast answers score more.","nl":"Tien seconden per vraag. Snel antwoorden levert meer op.","fr":"Dix secondes par question. Les réponses rapides rapportent plus.","de":"Zehn Sekunden pro Frage. Schnelle Antworten bringen mehr.","es":"Diez segundos por pregunta. Las respuestas rápidas puntúan más."}},{"id":"buzzer","en":"Buzzer","nl":"Buzzer","fr":"Buzzer","de":"Buzzer","es":"Pulsador","desc":{"en":"The first team to buzz answers out loud. Wrong? The others may buzz.","nl":"Het eerste team dat buzzt, antwoordt luidop. Fout? Dan mogen de anderen.","fr":"La première équipe qui buzze répond à voix haute. Faux ? Les autres peuvent buzzer.","de":"Das erste Team, das buzzert, antwortet laut. Falsch? Dann dürfen die anderen buzzern.","es":"El primer equipo en pulsar responde en voz alta. ¿Falla? Pueden pulsar los demás."}},{"id":"hotStreak","en":"Hot streak","nl":"Op dreef","fr":"Série en feu","de":"Glückssträhne","es":"Racha","desc":{"en":"Right answers in a row count up: 1x, 2x, 3x the points.","nl":"Juiste antwoorden op rij tellen op: 1x, 2x, 3x de punten.","fr":"Les bonnes réponses d'affilée comptent : 1x, 2x, 3x les points.","de":"Richtige Antworten in Folge zählen hoch: 1x, 2x, 3x die Punkte.","es":"Los aciertos seguidos suman más: 1x, 2x, 3x los puntos."}},{"id":"listRush","en":"List rush","nl":"Lijstjesrace","fr":"Course aux listes","de":"Listen-Rausch","es":"Lista exprés","desc":{"en":"Type as many items of the list as you can before time runs out.","nl":"Typ zoveel mogelijk items van het lijstje voor de tijd op is.","fr":"Tapez un maximum d'éléments de la liste avant la fin du temps.","de":"Tippe so viele Einträge der Liste wie möglich, bevor die Zeit abläuft.","es":"Escribe todos los elementos de la lista que puedas antes de que se acabe el tiempo."}}]},{"id":"strategy","name":{"en":"Strategy","nl":"Strategie","fr":"Stratégie","de":"Strategie","es":"Estrategia"},"rounds":[{"id":"lastStanding","en":"Last team standing","nl":"Wie blijft overeind","fr":"Le dernier debout","de":"Wer bleibt übrig","es":"El último en pie","desc":{"en":"One wrong answer and your team is out for the rest of the round.","nl":"Eén fout antwoord en je team ligt eruit voor de rest van de ronde.","fr":"Une mauvaise réponse et votre équipe est éliminée pour la manche.","de":"Eine falsche Antwort und dein Team ist für den Rest der Runde raus.","es":"Una respuesta mal y tu equipo queda fuera el resto de la ronda."}},{"id":"pushYourLuck","en":"Push your luck","nl":"Gok verder","fr":"Quitte ou double","de":"Alles oder nichts","es":"Tienta a la suerte","desc":{"en":"Every right answer doubles your pot. Bank it, or risk it all on the next question.","nl":"Elk juist antwoord verdubbelt je pot. Neem hem op, of waag alles op de volgende vraag.","fr":"Chaque bonne réponse double la cagnotte. Encaissez, ou risquez tout sur la suivante.","de":"Jede richtige Antwort verdoppelt deinen Topf. Sichere ihn oder riskiere alles bei der nächsten Frage.","es":"Cada acierto duplica tu bote. Plántate o arriésgalo todo en la siguiente pregunta."}},{"id":"steal","en":"Rob the leader","nl":"Beroof de leider","fr":"Volez le leader","de":"Beraube den Spitzenreiter","es":"Roba al líder","desc":{"en":"A right answer scores and takes the same points from the team in first place.","nl":"Een juist antwoord scoort en pikt evenveel punten van het team op kop.","fr":"Une bonne réponse marque et prend autant de points à l'équipe en tête.","de":"Eine richtige Antwort punktet und nimmt dem Team auf Platz eins genauso viele Punkte weg.","es":"Un acierto suma y le quita los mismos puntos al equipo en primer puesto."}},{"id":"pickYourLevel","en":"Pick your level","nl":"Kies je niveau","fr":"Choisissez votre niveau","de":"Wähl dein Level","es":"Elige tu nivel","desc":{"en":"See the topic, choose easy, medium or hard, and get your own question.","nl":"Zie het onderwerp, kies makkelijk, gemiddeld of moeilijk en krijg je eigen vraag.","fr":"Voyez le thème, choisissez facile, moyen ou difficile et recevez votre question.","de":"Sieh das Thema, wähle leicht, mittel oder schwer und bekomm deine eigene Frage.","es":"Mira el tema, elige fácil, medio o difícil y recibe tu propia pregunta."}},{"id":"stakeIt","en":"Stake it","nl":"Inzetten","fr":"Mise","de":"Setz alles","es":"Apuéstalo","desc":{"en":"See only the category, bet your points, then answer. Right wins the bet, wrong loses it.","nl":"Je ziet enkel de categorie, zet punten in en antwoord dan. Juist wint de inzet, fout verliest hem.","fr":"Voyez la catégorie, misez vos points, puis répondez. Juste gagne la mise, faux la perd.","de":"Sieh nur die Kategorie, setze deine Punkte, dann antworte. Richtig gewinnt den Einsatz, falsch verliert ihn.","es":"Solo ves la categoría, apuestas tus puntos y respondes. Si aciertas ganas la apuesta, si fallas la pierdes."}},{"id":"opponentsPick","en":"Your pick","nl":"Kies voor hen","fr":"Choix imposé","de":"Deine Wahl","es":"Tú eliges","desc":{"en":"The leading team picks the category for all the other teams, and sits that question out.","nl":"Het leidende team kiest de categorie voor alle andere teams en speelt die vraag zelf niet mee.","fr":"L'équipe en tête choisit la catégorie des autres et passe cette question.","de":"Das führende Team wählt die Kategorie für alle anderen Teams und setzt bei dieser Frage aus.","es":"El equipo líder elige la categoría para todos los demás y no juega esa pregunta."}}]},{"id":"party","name":{"en":"Party","nl":"Party","fr":"Fête","de":"Party","es":"Fiesta"},"rounds":[{"id":"crowdMind","en":"Think like the room","nl":"Denk als de zaal","fr":"Pensez comme la salle","de":"Denk wie der Saal","es":"Piensa como la sala","desc":{"en":"No right answer: score by giving the answer most teams give.","nl":"Geen juist antwoord: scoor door te antwoorden wat de meeste teams zeggen.","fr":"Pas de bonne réponse : marquez en donnant la réponse de la majorité.","de":"Keine richtige Antwort: Du punktest mit der Antwort, die die meisten Teams geben.","es":"No hay respuesta correcta: puntúas si das la respuesta que da la mayoría."}},{"id":"drawGuess","en":"Draw it","nl":"Teken het","fr":"Dessinez-le","de":"Zeichne es","es":"Dibújalo","desc":{"en":"Every team draws the same thing on its phone. Then everyone votes for the best drawing.","nl":"Elk team tekent hetzelfde op zijn telefoon. Daarna stemt iedereen op de beste tekening.","fr":"Chaque équipe dessine la même chose sur son téléphone, puis tout le monde vote pour le meilleur dessin.","de":"Jedes Team zeichnet dasselbe auf dem Handy. Dann stimmen alle für die beste Zeichnung.","es":"Todos los equipos dibujan lo mismo en el móvil. Luego todos votan el mejor dibujo."}},{"id":"captionThis","en":"Caption this","nl":"Onderschrift","fr":"Légende","de":"Bildunterschrift","es":"Ponle un pie","desc":{"en":"Write the funniest caption for the picture. Then vote for the best one.","nl":"Schrijf het grappigste onderschrift bij de foto. Stem daarna op het beste.","fr":"Écrivez la légende la plus drôle, puis votez pour la meilleure.","de":"Schreib die lustigste Unterschrift zum Bild. Dann stimmt für die beste.","es":"Escribe el pie de foto más gracioso. Luego votad el mejor."}},{"id":"bluffBank","en":"Bluff","nl":"Bluffen","fr":"Bluff","de":"Bluff","es":"Farol","desc":{"en":"Make up a believable answer, then find the real one between the bluffs.","nl":"Verzin een geloofwaardig antwoord en zoek dan het echte tussen de bluffs.","fr":"Inventez une réponse crédible, puis trouvez la vraie parmi les bluffs.","de":"Erfinde eine glaubwürdige Antwort und finde dann die echte zwischen den Bluffs.","es":"Inventa una respuesta creíble y luego encuentra la verdadera entre los faroles."}},{"id":"actItOut","en":"Act it out","nl":"Uitbeelden","fr":"Mime","de":"Pantomime","es":"Mímica","desc":{"en":"One team acts out a secret without words. The others type what it is.","nl":"Eén team beeldt een geheim uit zonder woorden. De anderen typen wat het is.","fr":"Une équipe mime un secret sans parler. Les autres tapent ce que c'est.","de":"Ein Team stellt ein Geheimnis ohne Worte dar. Die anderen tippen, was es ist.","es":"Un equipo representa un secreto sin palabras. Los demás escriben qué es."}},{"id":"photoHunt","en":"Photo hunt","nl":"Fotojacht","fr":"Chasse photo","de":"Fotojagd","es":"Caza de fotos","desc":{"en":"Take a photo for the task with your phone. Then vote for the best one.","nl":"Neem een foto voor de opdracht met je telefoon. Stem daarna op de beste.","fr":"Prenez une photo pour la mission, puis votez pour la meilleure.","de":"Mach mit dem Handy ein Foto zur Aufgabe. Dann stimmt für das beste.","es":"Haz una foto con el móvil para el reto. Luego votad la mejor."}},{"id":"whosWho","en":"Who wrote that?","nl":"Wie schreef dat?","fr":"Qui a écrit ça ?","de":"Wer hat das geschrieben?","es":"¿Quién lo escribió?","desc":{"en":"Every team answers a question about itself. Then guess which team wrote what.","nl":"Elk team beantwoordt een vraag over zichzelf. Raad daarna welk team wat schreef.","fr":"Chaque équipe répond à une question sur elle-même, puis devinez qui a écrit quoi.","de":"Jedes Team beantwortet eine Frage über sich selbst. Dann ratet, welches Team was geschrieben hat.","es":"Cada equipo responde una pregunta sobre sí mismo. Luego adivinad qué equipo escribió qué."}}]},{"id":"puzzle","name":{"en":"Puzzle","nl":"Puzzel","fr":"Énigmes","de":"Rätsel","es":"Acertijos"},"rounds":[{"id":"scramble","en":"Scramble","nl":"Letterhusselaar","fr":"Lettres mêlées","de":"Buchstabensalat","es":"Letras revueltas","desc":{"en":"The letters are shuffled. Find the word.","nl":"De letters zijn door elkaar gehusseld. Vind het woord.","fr":"Les lettres sont mélangées. Trouvez le mot.","de":"Die Buchstaben sind gemischt. Finde das Wort.","es":"Las letras están mezcladas. Encuentra la palabra."}},{"id":"commonThread","en":"Common thread","nl":"Rode draad","fr":"Fil rouge","de":"Roter Faden","es":"Hilo común","desc":{"en":"Clues appear one by one. What links them? Early is worth more.","nl":"Aanwijzingen verschijnen een voor een. Wat is de link? Vroeg raden levert meer op.","fr":"Les indices apparaissent un à un. Quel est le lien ? Trouver tôt rapporte plus.","de":"Hinweise erscheinen einer nach dem anderen. Was verbindet sie? Früh raten bringt mehr.","es":"Las pistas salen una a una. ¿Qué las une? Cuanto antes, más vale."}},{"id":"wordWeb","en":"Word web","nl":"Woordweb","fr":"Toile de mots","de":"Wortnetz","es":"Red de palabras","desc":{"en":"A board full of words hides groups of four. Teams find the groups on their phones and type what links each one. A point per group, a point per link.","nl":"Een bord vol woorden verbergt groepjes van vier. Teams zoeken de groepjes op hun gsm en typen wat ze verbindt. Een punt per groepje, een punt per verband.","fr":"Un tableau plein de mots cache des groupes de quatre. Les équipes trouvent les groupes sur leur téléphone et écrivent ce qui les relie. Un point par groupe, un point par lien.","de":"Ein Brett voller Wörter versteckt Vierergruppen. Die Teams finden die Gruppen auf dem Handy und schreiben, was sie verbindet. Ein Punkt pro Gruppe, ein Punkt pro Verbindung.","es":"Un tablero lleno de palabras esconde grupos de cuatro. Los equipos encuentran los grupos en el móvil y escriben qué los une. Un punto por grupo, un punto por conexión."}},{"id":"clueLadder","en":"Clue ladder","nl":"Hintladder","fr":"Échelle d'indices","de":"Hinweisleiter","es":"Escalera de pistas","desc":{"en":"Who or what is it? The clues go from very hard to easy. The sooner you know, the more points.","nl":"Wie of wat is het? De hints gaan van heel moeilijk naar makkelijk. Hoe sneller, hoe meer punten.","fr":"Qui ou quoi ? Les indices vont du très difficile au facile. Plus tôt vous trouvez, plus vous marquez.","de":"Wer oder was ist das? Die Hinweise gehen von sehr schwer bis leicht. Je früher du es weißt, desto mehr Punkte.","es":"¿Quién o qué es? Las pistas van de muy difíciles a fáciles. Cuanto antes lo sepas, más puntos."}}]},{"id":"special","name":{"en":"Special","nl":"Speciaal","fr":"Spécial","de":"Spezial","es":"Especiales"},"rounds":[{"id":"jackpot","en":"Jackpot question","nl":"Jackpotvraag","fr":"Question jackpot","de":"Jackpotfrage","es":"Pregunta bote","desc":{"en":"See the category, bet your points, then answer. Wrong loses the bet.","nl":"Zie de categorie, zet punten in en antwoord dan. Fout kost je inzet.","fr":"Voyez la catégorie, misez vos points, puis répondez. Faux = mise perdue.","de":"Sieh die Kategorie, setze deine Punkte, dann antworte. Falsch kostet den Einsatz.","es":"Mira la categoría, apuesta tus puntos y responde. Si fallas, pierdes la apuesta."}},{"id":"localLegend","en":"Local legend","nl":"Van bij ons","fr":"D'ici","de":"Lokalheld","es":"Leyenda local","desc":{"en":"Your own questions about the town, the club or the pub, with your own picture or logo.","nl":"Eigen vragen over het dorp, de club of het café, met je eigen foto of logo.","fr":"Vos propres questions sur la ville, le club ou le café, avec votre photo ou logo.","de":"Eure eigenen Fragen über den Ort, den Verein oder die Kneipe, mit eigenem Bild oder Logo.","es":"Vuestras propias preguntas sobre el pueblo, el club o el bar, con vuestra imagen o logo."}},{"id":"headToHead","en":"Head to head","nl":"Kop aan kop","fr":"Face à face","de":"Kopf an Kopf","es":"Cara a cara","desc":{"en":"Finale: the top two teams race for the answer. The other teams predict who wins.","nl":"Finale: de twee beste teams strijden om het antwoord. De anderen voorspellen wie wint.","fr":"Finale : les deux meilleures équipes s'affrontent. Les autres prédisent le gagnant.","de":"Finale: Die zwei besten Teams rennen um die Antwort. Die anderen Teams tippen auf den Sieger.","es":"Final: los dos mejores equipos compiten por la respuesta. Los demás pronostican quién gana."}}]},{"id":"clock","name":{"en":"Time as points","nl":"Tijd als punten","fr":"Le temps compte","de":"Zeit als Punkte","es":"El tiempo son puntos"},"rounds":[{"id":"clockBank","en":"Time bank","nl":"Tijdbank","fr":"Banque de temps","de":"Zeitbank","es":"Banco de tiempo","desc":{"en":"Every team starts with 60 seconds. Your clock only runs on your turn; a right answer wins seconds. At zero you are out.","nl":"Elk team start met 60 seconden. Je klok loopt enkel als je aan de beurt bent; een juist antwoord wint seconden. Op nul ben je eruit.","fr":"Chaque équipe a 60 secondes. Votre chrono ne tourne qu'à votre tour ; une bonne réponse rapporte des secondes. À zéro, vous êtes éliminés.","de":"Jedes Team startet mit 60 Sekunden. Deine Uhr läuft nur, wenn du dran bist; eine richtige Antwort bringt Sekunden. Bei null bist du raus.","es":"Cada equipo empieza con 60 segundos. Tu reloj solo corre en tu turno; un acierto suma segundos. A cero, quedas fuera."}},{"id":"clockDuel","en":"Clock duel","nl":"Klokduel","fr":"Duel chrono","de":"Uhrenduell","es":"Duelo de relojes","desc":{"en":"Finale: the top two take turns. Your clock runs until you answer right. The first clock at zero loses.","nl":"Finale: de twee beste teams om beurt. Je klok loopt tot je juist antwoordt. Wie eerst op nul staat, verliest.","fr":"Finale : les deux meilleures équipes à tour de rôle. Votre chrono tourne jusqu'à la bonne réponse. Le premier à zéro perd.","de":"Finale: Die besten zwei sind abwechselnd dran. Deine Uhr läuft, bis du richtig antwortest. Wessen Uhr zuerst null erreicht, verliert.","es":"Final: los dos mejores se turnan. Tu reloj corre hasta que aciertas. El primer reloj que llega a cero pierde."}}]}];
